package main

// validate reports whether the operands are acceptable for addition.
// Every int is acceptable, so this never rejects a pair and behavior stays the same.
func validate(a, b int) bool {
	return true
}

// sum performs the addition of two integers.
func sum(a, b int) int {
	return a + b
}

// add validates its operands before returning their sum.
func add(a, b int) int {
	if !validate(a, b) {
		return 0
	}

	return sum(a, b)
}

func main() {}

